89	    public OwnerRestControllerV1(ClinicService clinicService,
90	                                 OwnerMapper ownerMapper,
91	                                 PetMapper petMapper,
92	                                 VisitMapper visitMapper) {
93	        this.clinicService = clinicService;
94	        this.ownerMapper = ownerMapper;
95	        this.petMapper = petMapper;
96	        this.visitMapper = visitMapper;
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
102	        Collection<Owner> owners;
103	        if (lastName != null) {
104	            owners = this.clinicService.findOwnerByLastName(lastName);
105	        } else {
106	            owners = this.clinicService.findAllOwners();
107	        }
108	        if (owners.isEmpty()) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        List<OwnerDto> ownerDtos = owners.stream()
112	            .map(this::toOwnerDtoWithBulkWarning)
113	            .toList();
114	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(toOwnerDtoWithBulkWarning(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        List<String> missingFields = new ArrayList<>();
131	        requireNonBlank(missingFields, "firstName", ownerFieldsDto.getFirstName());
132	        requireNonBlank(missingFields, "lastName", ownerFieldsDto.getLastName());
133	        String normalizedAddress = normalizeAddress(ownerFieldsDto.getAddress());
134	        requireNonBlank(missingFields, "address", normalizedAddress);
135	        requireNonBlank(missingFields, "city", ownerFieldsDto.getCity());
136	        requireNonBlank(missingFields, "telephone", ownerFieldsDto.getTelephone());
137	        if (!missingFields.isEmpty()) {
138	            throw new MissingRequiredFieldsException(missingFields);
139	        }
140	        LocalDate suppliedOrDefaultDate = ownerFieldsDto.getRegistrationDate() != null
141	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
142	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
143	        requireDailyLimitNotReached(registrationDate);
144	        requireCityBelowCapacity(ownerFieldsDto.getCity());
145	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
146	        requireUniqueTelephone(normalizedTelephone);
147	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
148	        if (!sharesHousehold) {
149	            requireUniqueHousehold(ownerFieldsDto.getLastName(), normalizedAddress);
150	        }
151	        ownerFieldsDto.setTelephone(normalizedTelephone);
152	        if (ownerFieldsDto.getEmail() != null) {
153	            ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
154	        }
155	        HttpHeaders headers = new HttpHeaders();
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        owner.setAddress(normalizedAddress);
158	        owner.setRegistrationDate(registrationDate);
159	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
160	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
161	        if (sharesHousehold) {
162	            owner.setHouseholdId(joinHousehold(owner.getLastName(), owner.getAddress()));
163	        }
164	        this.clinicService.saveOwner(owner);
165	        AUDIT.info("Owner created id={} customerCode={} registrationDate={} membershipLevel={}",
166	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
167	            ownerMapper.toMembershipLevel(owner));
168	        OwnerDto ownerDto = toOwnerDtoWithBulkWarning(owner);
169	        headers.setLocation(UriComponentsBuilder.newInstance()
170	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
171	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
172	    }
173	
174	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
175	    @Override
176	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
177	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
178	        if (currentOwner == null) {
179	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	        }
181	        currentOwner.setAddress(ownerFieldsDto.getAddress());
182	        currentOwner.setCity(ownerFieldsDto.getCity());
183	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
184	        currentOwner.setLastName(ownerFieldsDto.getLastName());
185	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
186	        this.clinicService.saveOwner(currentOwner);
187	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
188	    }
