195	        if (owner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        this.clinicService.deleteOwner(owner);
199	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
200	    }
