202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
205	        Owner owner = this.clinicService.findOwnerById(ownerId);
206	        if (owner == null) {
207	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	        }
209	        HttpHeaders headers = new HttpHeaders();
210	        Pet pet = petMapper.toPet(petFieldsDto);
211	        owner.setId(ownerId);
212	        pet.setOwner(owner);
213	        pet.getType().setName(null);
214	        this.clinicService.savePet(pet);
215	        PetDto petDto = petMapper.toPetDto(pet);
216	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
217	            .buildAndExpand(pet.getId()).toUri());
218	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
219	    }
220	
221	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
222	    @Override
223	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
224	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
225	        if (currentOwner != null) {
226	            Pet currentPet = this.clinicService.findPetById(petId);
227	            if (currentPet != null) {
228	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
229	                currentPet.setName(petFieldsDto.getName());
230	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
231	                this.clinicService.savePet(currentPet);
232	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
233	            }
234	        }
235	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
236	    }
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
241	        HttpHeaders headers = new HttpHeaders();
242	        Visit visit = visitMapper.toVisit(visitFieldsDto);
243	        Pet pet = new Pet();
244	        pet.setId(petId);
245	        visit.setPet(pet);
246	        this.clinicService.saveVisit(visit);
247	        VisitDto visitDto = visitMapper.toVisitDto(visit);
248	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
249	            .buildAndExpand(visit.getId()).toUri());
250	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
251	    }
252	
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Override
256	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
257	        Owner owner = this.clinicService.findOwnerById(ownerId);
258	        if (owner != null) {
259	            Pet pet = owner.getPet(petId);
260	            if (pet != null) {
261	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
262	            }
263	        }
264	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
265	    }
266	
267	    /**
268	     * Builds the owner's customer code as {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the
269	     * upper-cased first three letters of {@code city}, {@code LAST3} the upper-cased first three letters
270	     * of {@code lastName}, and {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more
271	     * than the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
272	     *
273	     * @param city the owner's city (already validated non-blank)
274	     * @param lastName the owner's last name (already validated non-blank)
275	     * @return the formatted customer code for the owner being created
276	     */
277	    private String nextCustomerCode(String city, String lastName) {
278	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
279	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
280	        int sequence = (int) this.clinicService.findAllOwners().stream()
281	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
282	            .count() + 1;
283	        return String.format("%s-%s-%04d", city3, last3, sequence);
284	    }
285	
286	    /**
287	     * Counts the existing owners (those already persisted before this create) whose first and last
288	     * names both match the incoming owner's, compared case-insensitively. This snapshot is stored on
289	     * the new owner as its {@code namesakeCount} and echoed back on reads.
290	     *
291	     * @param firstName the incoming owner's first name (already validated non-blank)
292	     * @param lastName the incoming owner's last name (already validated non-blank)
293	     * @return the number of existing namesakes sharing both names case-insensitively
294	     */
295	    private int countNamesakes(String firstName, String lastName) {
296	        return (int) this.clinicService.findAllOwners().stream()
297	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
298	                && lastName.equalsIgnoreCase(existing.getLastName()))
299	            .count();
300	    }
301	
302	    /**
303	     * Records {@code fieldName} as missing when {@code value} is {@code null} or blank (empty or
304	     * whitespace-only), so the caller can reject the request listing every offending field.
305	     */
306	    private static void requireNonBlank(List<String> missingFields, String fieldName, String value) {
307	        if (value == null || value.isBlank()) {
308	            missingFields.add(fieldName);
309	        }
310	    }
311	
312	    /**
313	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. When the
314	     * value carries a leading {@code '+'} its country code is kept; otherwise a {@code '+61'} country
315	     * code is assumed and a single leading {@code '0'} is dropped from the national digits. The result
316	     * must be a {@code '+'} followed by 8 to 15 digits. For example {@code "0412 345 678"} becomes
317	     * {@code "+61412345678"}.
318	     *
319	     * @param telephone the raw telephone value from the request
320	     * @return the normalized E.164 telephone number (a {@code '+'} followed by 8 to 15 digits)
321	     * @throws InvalidFieldValueException if the value cannot form a valid E.164 number
322	     */
323	    private static String normalizeTelephone(String telephone) {
324	        String e164 = toE164(telephone);
325	        if (e164 == null) {
326	            throw new InvalidFieldValueException("telephone",
327	                "Telephone must be a valid E.164 number ('+' followed by 8 to 15 digits)");
328	        }
329	        return e164;
330	    }
331	
332	    /**
333	     * Converts a raw telephone value to E.164 form, or returns {@code null} when it cannot form a
334	     * valid E.164 number. Used both to normalize incoming values and to compare against existing
335	     * owners' stored numbers when detecting duplicates.
336	     */
337	    private static String toE164(String telephone) {
338	        if (telephone == null) {
339	            return null;
340	        }
341	        String cleaned = telephone.trim().replaceAll("[\\s\\-()]", "");
342	        String digits;
343	        if (cleaned.startsWith("+")) {
344	            digits = cleaned.substring(1);
345	        } else {
346	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
347	            digits = "61" + national;
348	        }
349	        if (!digits.matches("[0-9]{8,15}")) {
350	            return null;
351	        }
352	        return "+" + digits;
353	    }
354	
355	    /**
356	     * Validates and normalizes an owner's email address. A syntactically valid address is required;
357	     * the value is returned lower-cased so it is stored and echoed back in canonical form.
358	     *
359	     * @param email the raw email value from the request (already known to be non-null)
360	     * @return the lower-cased email to be stored and returned
361	     * @throws InvalidFieldValueException if the value is not a syntactically valid email address
362	     */
363	    private static String normalizeEmail(String email) {
364	        String trimmed = email.trim();
365	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
366	            throw new InvalidFieldValueException("email", "Email must be a syntactically valid address");
367	        }
368	        return trimmed.toLowerCase(Locale.ROOT);
369	    }
370	
371	    /** The maximum number of owners permitted in a single city; the {@code (50 + 1)}th is rejected. */
372	    private static final int MAX_OWNERS_PER_CITY = 50;
373	
374	    /**
375	     * Rejects the request when the owner's city already contains {@link #MAX_OWNERS_PER_CITY} or more
376	     * owners, comparing city names case-insensitively (consistent with the per-city customer-code
377	     * sequence). Callers reach this only once {@code city} has been validated non-blank.
378	     *
379	     * @param city the incoming owner's city (already validated non-blank)
380	     * @throws CityAtCapacityException if the city is already at or above its owner capacity
381	     */
382	    /** The maximum number of owners that may be registered in a single day; the {@code (100 + 1)}th is rejected. */
383	    private static final int MAX_OWNERS_PER_DAY = 100;
384	
385	    /**
386	     * Rejects the request when {@link #MAX_OWNERS_PER_DAY} or more owners have already been registered
387	     * on {@code businessDay}, counting existing owners whose {@code registrationDate} equals that date.
388	     * New owners take {@code businessDay} as their {@code registrationDate} (the supplied or defaulted
389	     * date rolled forward to a business day), so this caps the number that may be created per day.
390	     *
391	     * @param businessDay the adjusted business-day registration date of the owner being created
392	     * @throws DailyOwnerLimitException if the daily owner-creation limit has already been reached
393	     */
394	    /**
395	     * The number of owners for a single day beyond which the {@code bulkSignupWarning} flag is
396	     * raised; the warning is true once <em>more than</em> this many owners share a registration date.
397	     */
398	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
399	
400	    /**
401	     * Maps {@code owner} to its DTO and sets the {@code bulkSignupWarning} flag: {@code true} when
402	     * more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created for this
403	     * owner's registration date, otherwise {@code false}.
404	     *
405	     * @param owner the owner to map
406	     * @return the owner DTO with its bulk-signup warning flag populated
407	     */
408	    private OwnerDto toOwnerDtoWithBulkWarning(Owner owner) {
409	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
410	        ownerDto.setBulkSignupWarning(exceedsBulkSignupThreshold(owner.getRegistrationDate()));
411	        return ownerDto;
412	    }
413	
414	    /**
415	     * Returns whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
416	     * created on {@code registrationDate}, counting existing owners whose {@code registrationDate}
417	     * equals that date. Returns {@code false} when {@code registrationDate} is {@code null}.
418	     */
419	    private boolean exceedsBulkSignupThreshold(LocalDate registrationDate) {
420	        if (registrationDate == null) {
421	            return false;
422	        }
423	        long registeredThatDay = this.clinicService.findAllOwners().stream()
424	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
425	            .count();
426	        return registeredThatDay > BULK_SIGNUP_WARNING_THRESHOLD;
427	    }
428	
429	    private void requireDailyLimitNotReached(LocalDate businessDay) {
430	        long registeredThatDay = this.clinicService.findAllOwners().stream()
431	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
432	            .count();
433	        if (registeredThatDay >= MAX_OWNERS_PER_DAY) {
434	            throw new DailyOwnerLimitException(MAX_OWNERS_PER_DAY);
435	        }
436	    }
437	
438	    /**
439	     * Rolls {@code date} forward to a business day: when it falls on a Saturday or Sunday it advances
440	     * to the following Monday; a weekday is returned unchanged. Applied to the effective registration
441	     * date (whether supplied in the request or defaulted to the server date) so a weekend registration
442	     * is recorded on the next business day, and every value derived from the registration date uses the
443	     * adjusted date.
444	     *
445	     * @param date the effective registration date (supplied or defaulted), never {@code null}
446	     * @return the same date, or the next Monday when {@code date} is a weekend
447	     */
448	    private static LocalDate toBusinessDay(LocalDate date) {
449	        DayOfWeek day = date.getDayOfWeek();
450	        if (day == DayOfWeek.SATURDAY) {
451	            return date.plusDays(2);
452	        }
453	        if (day == DayOfWeek.SUNDAY) {
454	            return date.plusDays(1);
455	        }
456	        return date;
457	    }
458	
459	    private void requireCityBelowCapacity(String city) {
460	        long cityOwners = this.clinicService.findAllOwners().stream()
461	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
462	            .count();
463	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
464	            throw new CityAtCapacityException(city);
465	        }
466	    }
467	
468	    /**
469	     * Rejects the request when {@code normalizedTelephone} is already used by any existing owner,
470	     * comparing on the E.164 form so differently-formatted stored numbers still collide.
471	     *
472	     * @param normalizedTelephone the incoming owner's normalized E.164 telephone
473	     * @throws DuplicateTelephoneException if another owner already uses this telephone
474	     */
475	    private void requireUniqueTelephone(String normalizedTelephone) {
476	        boolean taken = this.clinicService.findAllOwners().stream()
477	            .map(Owner::getTelephone)
478	            .map(OwnerRestControllerV1::toE164)
479	            .filter(existing -> existing != null)
480	            .anyMatch(normalizedTelephone::equals);
481	        if (taken) {
482	            throw new DuplicateTelephoneException(normalizedTelephone);
483	        }
484	    }
485	
486	    /**
487	     * Rejects the request when another owner already shares this household, i.e. has both the same
488	     * last name and the same address once each value is normalized (trimmed, internal whitespace
489	     * runs collapsed to a single space, and compared case-insensitively). Callers skip this check
490	     * when the request opts in via {@code sharesHousehold}.
491	     *
492	     * @param lastName the incoming owner's last name (already validated non-blank)
493	     * @param address the incoming owner's address (already validated non-blank)
494	     * @throws DuplicateHouseholdException if another owner already has this last name and address
495	     */
496	    private void requireUniqueHousehold(String lastName, String address) {
497	        String normalizedLastName = normalizeForHousehold(lastName);
498	        String normalizedAddress = householdAddressKey(address);
499	        boolean taken = this.clinicService.findAllOwners().stream()
500	            .anyMatch(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
501	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress));
502	        if (taken) {
503	            throw new DuplicateHouseholdException(lastName, address);
504	        }
505	    }
506	
507	    /**
508	     * Normalizes a value for household-duplicate comparison: trims leading and trailing whitespace,
509	     * collapses every internal run of whitespace to a single space, and lower-cases the result so
510	     * comparisons are case-insensitive.
511	     */
512	    private static String normalizeForHousehold(String value) {
513	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
514	    }
515	
516	    /**
517	     * Normalizes an owner's address to its canonical stored form: leading and trailing whitespace is
518	     * trimmed, every internal run of whitespace is collapsed to a single space, the value is
519	     * upper-cased, and common street-type abbreviations are expanded on a whole-word basis
520	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or whitespace-only
521	     * value normalizes to the empty string, so the required-field check rejects an address that is
522	     * blank once normalized. For example {@code "  12  main  st "} becomes {@code "12 MAIN STREET"}.
523	     *
524	     * @param address the raw address value from the request (may be {@code null})
525	     * @return the normalized address, or the empty string when blank after normalization
526	     */
527	    private static String normalizeAddress(String address) {
528	        if (address == null) {
529	            return "";
530	        }
531	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
532	        if (collapsed.isEmpty()) {
533	            return "";
534	        }
535	        String[] tokens = collapsed.split(" ");
536	        StringBuilder sb = new StringBuilder();
537	        for (String token : tokens) {
538	            String expanded = switch (token) {
539	                case "ST" -> "STREET";
540	                case "RD" -> "ROAD";
541	                case "AVE" -> "AVENUE";
542	                default -> token;
543	            };
544	            if (sb.length() > 0) {
545	                sb.append(' ');
546	            }
547	            sb.append(expanded);
548	        }
549	        return sb.toString();
550	    }
551	
552	    /**
553	     * Derives the comparison key for an address used by household-duplicate detection and the shared
554	     * household identifier: the address is first put in its canonical normalized form and then
555	     * lower-cased and whitespace-collapsed, so every comparison and the derived id agree on the
556	     * normalized address regardless of the raw casing, spacing or abbreviations supplied.
557	     */
558	    private static String householdAddressKey(String address) {
559	        return normalizeForHousehold(normalizeAddress(address));
560	    }
561	
562	    /**
563	     * Joins the household identified by this last name and address, returning the stable shared
564	     * {@code householdId} to store on the joining owner. The identifier is derived deterministically
565	     * from the normalized last name and address, so every owner in the same household resolves to the
566	     * same value. Any existing household members that predate this feature (or were created without
567	     * opting in) are back-filled with the shared identifier so the whole household agrees.
568	     *
569	     * @param lastName the joining owner's last name (already validated non-blank)
570	     * @param address the joining owner's address (already validated non-blank)
571	     * @return the shared household identifier for this last name and address
572	     */
573	    private String joinHousehold(String lastName, String address) {
574	        String normalizedLastName = normalizeForHousehold(lastName);
575	        String normalizedAddress = householdAddressKey(address);
576	        String householdId = householdIdFor(normalizedLastName, normalizedAddress);
577	        this.clinicService.findAllOwners().stream()
578	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
579	                && householdAddressKey(existing.getAddress()).equals(normalizedAddress))
580	            .filter(existing -> !householdId.equals(existing.getHouseholdId()))
581	            .forEach(existing -> {
582	                existing.setHouseholdId(householdId);
583	                this.clinicService.saveOwner(existing);
584	            });
585	        return householdId;
586	    }
587	
588	    /**
589	     * Derives a stable household identifier from the already-normalized last name and address as the
590	     * upper-cased first 12 hex characters of their SHA-256 digest. Deterministic so the same household
591	     * always maps to the same identifier.
592	     */
593	    private static String householdIdFor(String normalizedLastName, String normalizedAddress) {
594	        try {
595	            byte[] digest = MessageDigest.getInstance("SHA-256")
596	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
597	            StringBuilder sb = new StringBuilder();
598	            for (byte b : digest) {
599	                sb.append(String.format("%02X", b));
600	            }
601	            return sb.substring(0, 12);
602	        }
603	        catch (NoSuchAlgorithmException e) {
604	            throw new IllegalStateException("SHA-256 not available", e);
605	        }
606	    }
607	}
